"""Independent 2005/A-D answers."""
import json
from pathlib import Path
TEACHER=r'''#include <bits/stdc++.h>
using namespace std;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n,m,q;cin>>n>>m>>q;vector<int>b(m);for(int&x:b)cin>>x;sort(b.begin(),b.end());while(q--){int a;cin>>a;auto it=lower_bound(b.begin(),b.end(),a);if(it==b.begin())cout<<b.front()-1;else if(it==b.end())cout<<n-b.back();else cout<<(*it-*prev(it))/2;cout<<'\n';}}}'''
WHY='Only the nearest teacher on each side matters. Outside the teacher span David runs toward the corresponding wall, yielding b_min-1 or n-b_max moves. Between teachers at L,R, they close inward and David can stay near their midpoint, giving floor((R-L)/2). Sort teacher positions and locate neighbors by binary search. O(m log m+q log m) time, O(m) space. This solves both versions.'
ANSWERS=[
('2005/A','Every vowel with frequency c contributes at least 2^c-1 nonempty constant palindromes. Convexity minimizes their sum by balancing the five frequencies. Place equal vowels in contiguous blocks so no palindrome uses multiple different vowels, attaining the lower bound. O(n) time and O(1) auxiliary space.',r'''#include <bits/stdc++.h>
using namespace std;int main(){int t;cin>>t;string v="aeiou";while(t--){int n;cin>>n;for(int i=0;i<5;i++)cout<<string(n/5+(i<n%5),v[i]);cout<<'\n';}}'''),
('2005/B1',WHY,TEACHER),('2005/B2',WHY,TEACHER),
('2005/C','Maintain five DP states: the number of already matched letters of the next narek. For each included string, scan from each starting state, awarding +1 for a desired letter, -1 for another letter in narek, zero otherwise; wrap after k. Skipping leaves state unchanged. At the end a partial match of length j was provisionally credited +j but must be penalized -j, so subtract 2j. Maximize over states and zero. O(5nm) time and O(5) DP space aside from one input string.',r'''#include <bits/stdc++.h>
using namespace std;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;string word="narek";while(t--){int n,m;cin>>n>>m;vector<int>dp(5,-1000000000);dp[0]=0;while(n--){string s;cin>>s;vector<int>nd=dp;for(int st=0;st<5;st++){int cur=st,gain=0;for(char c:s)if(c==word[cur]){gain++;cur=(cur+1)%5;}else if(word.find(c)!=string::npos)gain--;nd[cur]=max(nd[cur],dp[st]+gain);}dp.swap(nd);}int ans=0;for(int j=0;j<5;j++)ans=max(ans,dp[j]-2*j);cout<<ans<<'\n';}}'''),
('2005/D','For each right endpoint r maintain compressed states (x,y,count) for all swap intervals [l,r], where x=gcd(original A prefix before l, B[l..r]) and y symmetrically. Extending r applies gcd(x,B[r]) and gcd(y,A[r]); starting l=r adds one state from original prefix GCDs. Merge identical states and keep multiplicity. Appending original suffix GCDs gives the final score, counted for every interval. Prefix/suffix GCDs are precomputed. Each coordinate has logarithmically many distinct divisors within each constant prefix region; compression avoids enumerating all intervals. O(n log^2 V log log V) expected small-state work, O(n+log^2 V) space.',r'''#include <bits/stdc++.h>
using namespace std;using ll=long long;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n;cin>>n;vector<int>a(n),b(n),pa(n+1),pb(n+1),sa(n+1),sb(n+1);for(int&x:a)cin>>x;for(int&x:b)cin>>x;for(int i=0;i<n;i++){pa[i+1]=__gcd(pa[i],a[i]);pb[i+1]=__gcd(pb[i],b[i]);}for(int i=n-1;i>=0;i--){sa[i]=__gcd(sa[i+1],a[i]);sb[i]=__gcd(sb[i+1],b[i]);}map<pair<int,int>,ll>states;ll ways=0;int best=0;for(int r=0;r<n;r++){map<pair<int,int>,ll>next;for(auto e:states)next[{__gcd(e.first.first,b[r]),__gcd(e.first.second,a[r])}]+=e.second;next[{__gcd(pa[r],b[r]),__gcd(pb[r],a[r])}]++;states.swap(next);for(auto e:states){int score=__gcd(e.first.first,sa[r+1])+__gcd(e.first.second,sb[r+1]);if(score>best){best=score;ways=e.second;}else if(score==best)ways+=e.second;}}cout<<best<<' '<<ways<<'\n';}}''')]
if __name__=='__main__':
    p=Path('backend/data/bench/codeforces700_20261116/assistant_answers_v1/shard_test_000_199.jsonl')
    with p.open('a',encoding='utf-8') as out:
        for ident,explanation,code in ANSWERS:
            out.write(json.dumps({'id':ident,'split':'test','author':'current chat assistant','status':'authored','explanation':explanation,'cpp_code':code,'validation':'not executed'})+'\n')
